"use client";

import LedDropdown from "./ledDropdown";
import LedPreview from "./ledPreview";
import { LedType } from "@/types/led";

export interface LedMappingData {
  left1Label: LedType;
  left2Label: LedType;
  left3Label: LedType;
  right1Label: LedType;
  right2Label: LedType;
  right3Label: LedType;
}

interface Props {
  value: LedMappingData;
  onChange: (value: LedMappingData) => void;
}

export default function LedMapping({ value, onChange }: Props) {
  const selected = [
    value.left1Label,
    value.left2Label,
    value.left3Label,
    value.right1Label,
    value.right2Label,
    value.right3Label,
  ];

  const update = (key: keyof LedMappingData, newLed: LedType) => {
    const updated = { ...value };
    const oldLed = updated[key];

    const existingKey = (Object.keys(updated) as (keyof LedMappingData)[]).find(
      (k) => k !== key && updated[k] === newLed
    );

    if (existingKey) {
      updated[existingKey] = oldLed;
    }

    updated[key] = newLed;
    onChange(updated);
  };

  return (
    <div>
      {/* LEFT / RIGHT columns */}
      <div className="grid gap-x-6 gap-y-2 sm:grid-cols-2">
        {/* LEFT */}
        <div className="space-y-2">
          <p className="text-[10px] font-semibold tracking-[0.2em] text-blue-400/80">
            LEFT
          </p>

          <LedDropdown
            label="L1"
            value={value.left1Label}
            selectedValues={selected}
            onChange={(v) => update("left1Label", v)}
          />
          <LedDropdown
            label="L2"
            value={value.left2Label}
            selectedValues={selected}
            onChange={(v) => update("left2Label", v)}
          />
          <LedDropdown
            label="L3"
            value={value.left3Label}
            selectedValues={selected}
            onChange={(v) => update("left3Label", v)}
          />
        </div>

        {/* RIGHT */}
        <div className="space-y-2">
          <p className="text-[10px] font-semibold tracking-[0.2em] text-red-400/80">
            RIGHT
          </p>

          <LedDropdown
            label="R1"
            value={value.right1Label}
            selectedValues={selected}
            onChange={(v) => update("right1Label", v)}
          />
          <LedDropdown
            label="R2"
            value={value.right2Label}
            selectedValues={selected}
            onChange={(v) => update("right2Label", v)}
          />
          <LedDropdown
            label="R3"
            value={value.right3Label}
            selectedValues={selected}
            onChange={(v) => update("right3Label", v)}
          />
        </div>
      </div>

      {/* Preview */}
      <div className="mt-4 border-t border-zinc-800 pt-4">
        <LedPreview
          left1Label={value.left1Label}
          left2Label={value.left2Label}
          left3Label={value.left3Label}
          right1Label={value.right1Label}
          right2Label={value.right2Label}
          right3Label={value.right3Label}
        />
      </div>
    </div>
  );
}
