export interface ApiResponse<T> {
  success: boolean;
  data?: T;
  count?: number;
  error?: string;
  message?: string;
}

export interface PaginationMeta {
  page: number;
  limit: number;
  totalCount: number;
  totalPages: number;
  hasNextPage: boolean;
  hasPrevPage: boolean;
}

export interface PaginatedApiResponse<T> {
  success: boolean;
  data?: T;
  pagination?: PaginationMeta;
  error?: string;
  message?: string;
}

/* ==================================================
   GET ALL SMART METERS
================================================== */

export async function getAllSmartMeters(params?: {
  status?: string;
  include?: boolean;
  page?: number;
  limit?: number;
  search?: string;
}): Promise<PaginatedApiResponse<SmartMeter[]>> {
  try {
    const queryParams = new URLSearchParams();

    if (params?.status)
      queryParams.append("status", params.status);

    if (params?.include)
      queryParams.append("include", "true");

    if (params?.page)
      queryParams.append("page", params.page.toString());

    if (params?.limit)
      queryParams.append("limit", params.limit.toString());

    if (params?.search)
      queryParams.append("search", params.search);

    const response = await fetch(
      `${API_BASE_URL}/api/smartmeters${
        queryParams.toString()
          ? `?${queryParams.toString()}`
          : ""
      }`,
      {
        method: "GET",
        credentials: "include",
        cache: "no-store",
        headers: {
          "Content-Type": "application/json",
        },
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      console.log(errorData);

      throw new Error(
        errorData.error || "Failed to fetch Smart Meters"
      );
    }

    return await response.json();
  } catch (error) {
    console.error("Error fetching Smart Meters:", error);

    return {
      success: false,
      error:
        error instanceof Error
          ? error.message
          : "Failed to fetch Smart Meters",
    };
  }
}

