"use client";

import { Trash2, Cpu } from "lucide-react";
import { Input } from "@/components/ui/input";
import LedMapping, { LedMappingData } from "./ledMapping";

interface MediaConverter {
  mediaConverterId: string;
  left1Label: any;
  left2Label: any;
  left3Label: any;
  right1Label: any;
  right2Label: any;
  right3Label: any;
}

interface Props {
  index: number;
  converter: MediaConverter;
  onIdChange: (id: string) => void;
  onMappingChange: (mapping: LedMappingData) => void;
  onRemove: () => void;
  removable: boolean;
}

export default function MediaConverterCard({
  index,
  converter,
  onIdChange,
  onMappingChange,
  onRemove,
  removable,
}: Props) {
  return (
    <div className="rounded-xl border border-zinc-800 bg-zinc-900/90 transition-colors duration-200 hover:border-red-700/40">
      {/* Header row: icon, index, ID input, remove */}
      <div className="flex items-center gap-3 border-b border-zinc-800 px-4 py-3">
        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border border-zinc-700 bg-zinc-950 text-red-500">
          <Cpu className="h-4 w-4" />
        </div>

        <span className="shrink-0 text-xs font-medium text-zinc-400">
          Converter {index + 1}
        </span>

        <div className="h-4 w-px shrink-0 bg-zinc-800" />

        <Input
          value={converter.mediaConverterId}
          placeholder="MC-001"
          onChange={(e) => onIdChange(e.target.value)}
          className="h-8 w-32 border-zinc-700 bg-zinc-950 font-mono text-xs text-white focus:border-red-700 focus:ring-1 focus:ring-red-700/30"
        />

        <div className="flex-1" />

        {removable && (
          <button
            type="button"
            onClick={onRemove}
            aria-label="Remove media converter"
            className="rounded-md p-1.5 text-zinc-500 transition-all duration-200 hover:bg-red-500/10 hover:text-red-400 active:scale-95"
          >
            <Trash2 className="h-4 w-4" />
          </button>
        )}
      </div>

      {/* LED mapping */}
      <div className="p-4">
        <LedMapping
          value={{
            left1Label: converter.left1Label,
            left2Label: converter.left2Label,
            left3Label: converter.left3Label,
            right1Label: converter.right1Label,
            right2Label: converter.right2Label,
            right3Label: converter.right3Label,
          }}
          onChange={onMappingChange}
        />
      </div>
    </div>
  );
}
